export type ParsedJuplendWithdrawInstruction<
  TProgram extends string = typeof MARGINFI_PROGRAM_ADDRESS,
  TAccountMetas extends readonly AccountMeta[] = readonly AccountMeta[],
> = {
  programAddress: Address<TProgram>;
  accounts: {
    group: TAccountMetas[0];
    marginfiAccount: TAccountMetas[1];
    authority: TAccountMetas[2];
    bank: TAccountMetas[3];
    /**
     * Token account that will receive the underlying withdrawal.
     * WARN: Completely unchecked!
     */
    destinationTokenAccount: TAccountMetas[4];
    /**
     * The bank's liquidity vault authority PDA (acts as signer for JupLend CPIs).
     * NOTE: JupLend marks the signer as writable in their withdraw instruction.
     */
    liquidityVaultAuthority: TAccountMetas[5];
    /** Underlying mint. */
    mint: TAccountMetas[6];
    /** JupLend lending state account. */
    integrationAcc1: TAccountMetas[7];
    /** JupLend fToken mint. */
    fTokenMint: TAccountMetas[8];
    /** Bank's fToken vault (validated via has_one on bank). */
    integrationAcc2: TAccountMetas[9];
    /**
     * Withdraw intermediary ATA (authority = liquidity_vault_authority).
     * This must be an ATA to satisfy JupLend's withdraw constraints.
     */
    integrationAcc3: TAccountMetas[10];
    lendingAdmin: TAccountMetas[11];
    supplyTokenReservesLiquidity: TAccountMetas[12];
    lendingSupplyPositionOnLiquidity: TAccountMetas[13];
    rateModel: TAccountMetas[14];
    vault: TAccountMetas[15];
    /**
     * JupLend claim account for liquidity_vault_authority.
     * TEMPORARY: Mainnet currently requires this account (passing None causes ConstraintMut errors),
     * but an upcoming upgrade is expected to make it truly optional. The account is never actually
     * validated or used - you can pass any mutable account. We create the canonical PDA for consistency.
     * Seeds: ["user_claim", liquidity_vault_authority, mint] on Liquidity program.
     */
    claimAccount: TAccountMetas[16];
    liquidity: TAccountMetas[17];
    liquidityProgram: TAccountMetas[18];
    rewardsRateModel: TAccountMetas[19];
    juplendProgram: TAccountMetas[20];
    tokenProgram: TAccountMetas[21];
    associatedTokenProgram: TAccountMetas[22];
    systemProgram: TAccountMetas[23];
  };
  data: JuplendWithdrawInstructionData;
};

export function parseJuplendWithdrawInstruction<
  TProgram extends string,
  TAccountMetas extends readonly AccountMeta[],
>(
  instruction: Instruction<TProgram> &
    InstructionWithAccounts<TAccountMetas> &
    InstructionWithData<ReadonlyUint8Array>
): ParsedJuplendWithdrawInstruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 24) {
    throw new SolanaError(SOLANA_ERROR__PROGRAM_CLIENTS__INSUFFICIENT_ACCOUNT_METAS, {
      actualAccountMetas: instruction.accounts.length,
      expectedAccountMetas: 24,
    });
  }
  let accountIndex = 0;
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!;
    accountIndex += 1;
    return accountMeta;
  };
  return {
    programAddress: instruction.programAddress,
    accounts: {
      group: getNextAccount(),
      marginfiAccount: getNextAccount(),
      authority: getNextAccount(),
      bank: getNextAccount(),
      destinationTokenAccount: getNextAccount(),
      liquidityVaultAuthority: getNextAccount(),
      mint: getNextAccount(),
      integrationAcc1: getNextAccount(),
      fTokenMint: getNextAccount(),
      integrationAcc2: getNextAccount(),
      integrationAcc3: getNextAccount(),
      lendingAdmin: getNextAccount(),
      supplyTokenReservesLiquidity: getNextAccount(),
      lendingSupplyPositionOnLiquidity: getNextAccount(),
      rateModel: getNextAccount(),
      vault: getNextAccount(),
      claimAccount: getNextAccount(),
      liquidity: getNextAccount(),
      liquidityProgram: getNextAccount(),
      rewardsRateModel: getNextAccount(),
      juplendProgram: getNextAccount(),
      tokenProgram: getNextAccount(),
      associatedTokenProgram: getNextAccount(),
      systemProgram: getNextAccount(),
    },
    data: getJuplendWithdrawInstructionDataDecoder().decode(instruction.data),
  };
}
